exercises.solution:
SELECT DISTINCT customer_id
FROM orders
ORDER BY customer_id;

SELECT c.category_id,
       c.category_name
FROM categories AS c
WHERE NOT EXISTS (
    SELECT 1 FROM products AS p WHERE p.category = c.category_name
);

SELECT (SELECT COUNT(*) FROM suppliers)  AS supplier_rows,
       (SELECT COUNT(*) FROM categories) AS category_rows,
       (SELECT COUNT(*) FROM suppliers NATURAL JOIN categories) AS natural_rows;

SELECT t.value AS tag,
       COUNT(*) AS order_count
FROM raw_order_events AS r,
     json_each(r.payload, '$.tags') AS t
GROUP BY t.value
ORDER BY order_count DESC, tag;

/* Snowflake notes:
SELECT f.value::string AS tag, COUNT(*) AS order_count FROM raw_order_events r,
LATERAL FLATTEN(input => PARSE_JSON(r.payload):tags) f GROUP BY 1 ORDER BY 2 DESC, 1;
*/

SELECT product_id, product_name, list_price
FROM products
WHERE list_price > (SELECT AVG(list_price) FROM products);

SELECT product_id, product_name
FROM products
WHERE product_id NOT IN (SELECT product_id FROM order_items);

SELECT o.customer_id, o.order_id, o.order_date, o.order_status
FROM orders AS o
WHERE o.order_date = (SELECT MAX(o2.order_date)
                      FROM orders AS o2
                      WHERE o2.customer_id = o.customer_id);

/* Snowflake notes:
SELECT * FROM orders QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY
order_date DESC, order_id DESC) = 1;
*/

SELECT c.customer_id, c.name
FROM customers AS c
WHERE EXISTS (SELECT 1 FROM orders AS o WHERE o.customer_id = c.customer_id);

SELECT c.customer_id, c.name, c.signup_date
FROM customers AS c
WHERE NOT EXISTS (SELECT 1 FROM orders AS o WHERE o.customer_id = c.customer_id);

SELECT o.order_id, o.order_date, o.order_status
FROM orders AS o
WHERE NOT EXISTS (SELECT 1 FROM order_items AS i WHERE i.order_id = o.order_id);

SELECT o.order_id, o.customer_id, o.order_date, o.order_status
FROM orders AS o
WHERE NOT EXISTS (SELECT 1 FROM customers AS c WHERE c.customer_id = o.customer_id);

SELECT s.supplier_id, s.supplier_name
FROM suppliers AS s
WHERE NOT EXISTS (SELECT 1 FROM products AS p WHERE p.supplier_id = s.supplier_id);

SELECT customer_id FROM customers
UNION
SELECT customer_id FROM orders;

SELECT product_id FROM products
EXCEPT
SELECT i.product_id
FROM order_items AS i
JOIN orders AS o ON o.order_id = i.order_id
WHERE o.order_status IN ('completed', 'shipped', 'returned');

/* Snowflake notes:
SELECT product_id FROM products MINUS SELECT ...;
*/

WITH RECURSIVE nums(month_number) AS (
    SELECT 1
    UNION ALL
    SELECT month_number + 1 FROM nums WHERE month_number < 12
)
SELECT month_number FROM nums;

/* Snowflake notes:
SELECT ROW_NUMBER() OVER (ORDER BY SEQ4()) AS month_number FROM
TABLE(GENERATOR(ROWCOUNT => 12));
*/

SELECT strftime('%Y-%m', order_date) AS order_month,
       COUNT(*)                        AS order_count
FROM orders
GROUP BY order_month
ORDER BY order_month;

/* Snowflake notes:
SELECT TO_CHAR(DATE_TRUNC('month', order_date), 'YYYY-MM') AS order_month, COUNT(*) AS
order_count FROM orders GROUP BY 1 ORDER BY 1;
*/

SELECT customer_id, name, email
FROM customers
WHERE LOWER(name) LIKE '%johnson%';

/* Snowflake notes:
SELECT customer_id, name, email FROM customers WHERE name ILIKE '%johnson%';
*/

SELECT product_id,
       COALESCE(category, 'Uncategorized')                          AS category,
       COALESCE(list_price, 0)                                      AS list_price,
       CASE WHEN list_price >= 100 THEN 'premium' ELSE 'standard' END AS price_band
FROM products;

/* Snowflake notes:
SELECT product_id, NVL(category, 'Uncategorized') AS category, ZEROIFNULL(list_price)
AS list_price, IFF(list_price >= 100, 'premium', 'standard') AS price_band FROM
products;
*/

SELECT event_id,
       payload ->> '$.order_id'    AS order_id,
       payload ->> '$.placed_at'   AS placed_at,
       payload ->> '$.customer.id' AS customer_id
FROM raw_order_events;

/* Snowflake notes:
SELECT event_id, payload:order_id::INT AS order_id, payload:placed_at::STRING AS
placed_at, payload:customer.id::INT AS customer_id FROM raw_order_events;
*/

SELECT COALESCE(payload ->> '$.customer.tier', 'none') AS tier,
       COUNT(*)                                        AS events
FROM raw_order_events
GROUP BY COALESCE(payload ->> '$.customer.tier', 'none');

/* Snowflake notes:
SELECT NVL(payload:customer.tier::STRING, 'none') AS tier, COUNT(*) AS events FROM
raw_order_events GROUP BY 1;
*/

SELECT CASE WHEN json_type(payload, '$.customer.tier') IS NOT NULL THEN 1 ELSE 0 END AS has_tier,
       CASE WHEN json_type(payload, '$.tags') IS NOT NULL THEN 1 ELSE 0 END          AS has_tags,
       COUNT(*)                                                                      AS events
FROM raw_order_events
GROUP BY has_tier, has_tags;

/* Snowflake notes:
SELECT IFF(payload:customer:tier IS NOT NULL, 1, 0) AS has_tier, IFF(payload:tags IS
NOT NULL, 1, 0) AS has_tags, COUNT(*) AS events FROM raw_order_events GROUP BY 1, 2;
*/

SELECT json_array_length(payload, '$.items') AS item_count,
       COUNT(*)                              AS events
FROM raw_order_events
GROUP BY json_array_length(payload, '$.items');

/* Snowflake notes:
SELECT ARRAY_SIZE(payload:items) AS item_count, COUNT(*) AS events FROM
raw_order_events GROUP BY 1;
*/

SELECT customer_id,
       json_object('name', name, 'email', email, 'signup_date', signup_date) AS profile
FROM customers
WHERE region = 'East';

/* Snowflake notes:
SELECT customer_id, OBJECT_CONSTRUCT_KEEP_NULL('name', name, 'email', email,
'signup_date', signup_date) AS profile FROM customers WHERE region = 'East';
*/

SELECT t.value   AS tag,
       COUNT(*)  AS tagged_events
FROM raw_order_events AS e,
     json_each(e.payload, '$.tags') AS t
GROUP BY t.value;

/* Snowflake notes:
SELECT t.value::STRING AS tag, COUNT(*) AS tagged_events FROM raw_order_events e,
LATERAL FLATTEN(input => e.payload:tags) t GROUP BY 1;
*/

SELECT e.payload ->> '$.order_id' AS order_id,
       t.value                  AS tag
FROM raw_order_events AS e
LEFT JOIN json_each(e.payload, '$.tags') AS t ON 1 = 1
WHERE e.payload ->> '$.customer.id' = 7;

/* Snowflake notes:
SELECT e.payload:order_id::INT AS order_id, t.value::STRING AS tag FROM
raw_order_events e, LATERAL FLATTEN(input => e.payload:tags, OUTER => TRUE) t WHERE
e.payload:customer.id::INT = 7;
*/

SELECT tbl_name  AS table_name,
       COUNT(*)  AS index_count
FROM sqlite_master
WHERE type = 'index'
GROUP BY tbl_name;

/* Snowflake notes:
SELECT table_name, clustering_key FROM information_schema.tables WHERE table_schema =
'PUBLIC';
*/

SELECT order_id, order_date, order_status
FROM orders
WHERE order_status IN ('cancelled', 'pending');

/* Snowflake notes:
SELECT order_id, order_date, order_status FROM orders WHERE order_status IN
('cancelled','pending');
*/

SELECT c.customer_id, c.name
FROM customers AS c
WHERE NOT EXISTS (
    SELECT 1 FROM orders AS o
    WHERE o.customer_id = c.customer_id
      AND o.order_status IN ('completed','shipped','returned')
);

/* Snowflake notes:
Same NOT EXISTS query.
*/
